+        preflight_failed)                        verdict_color "warn" ;;
+        *)                                       printf '%s' "${YELLOW:-}" ;;
     esac
 }

@@ -943,6 +951,7 @@ _render_pipeline_end() {
         failed)                  word="failed" ;;
